        "a6ae2250b08f454e89c68c560d7a01a3": {
          "id": "a6ae2250b08f454e89c68c560d7a01a3",
          "stepType": "ImageOutput",
          "name": "Image",
          "url": {
            "value": "(function execute() {\n    /* Return a quoted string.  For example:\n\n       if (vaInputs.first_name == 'Bill') {\n           return gs.getMessageLang(\"hi there {0}\", vaContext.getRequesterLang(), [vaInputs.first_name]);\n       } else {\n           return gs.getMessageLang(\"how are you {0}\", vaContext.getRequesterLang(), [vaInputs.last_name]);\n       }\n    */\n    return vaVars.baseUri + vaVars.image;\n})()\n",
            "mode": "script"
          },
          "altText": {
            "value": "",
            "mode": "simple"
          },
          "variableId": "",
          "applicability": {
            "mode": "script",
            "value": "(function execute() {\n\n    return vaVars.catalog_item_id != '' && vaInputs.search == '' && vaVars.image_not_shown;\n    \n})()\n"
          },
          "cardMetadata": {
            "mode": "card",
            "metadataScript": "",
